functions.bootstrap_platform_admin:
CREATE OR REPLACE FUNCTION public.bootstrap_platform_admin(p_email text, p_password_hash text, p_full_name text)
 RETURNS TABLE(user_id uuid, email text, full_name text, role text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_existing_count INT;
  v_user_id UUID;
BEGIN
  PERFORM pg_advisory_xact_lock(784512903);

  SELECT COUNT(*) INTO v_existing_count
  FROM public.platform_staff ps
  JOIN public.users u ON u.id = ps.user_id
  WHERE u.deleted_at IS NULL;

  IF v_existing_count > 0 THEN
    RAISE EXCEPTION 'PLATFORM_ADMIN_ALREADY_EXISTS';
  END IF;

  INSERT INTO public.users (email, user_kind, password_hash, full_name, status)
  VALUES (lower(trim(p_email)), 'platform_admin', p_password_hash, trim(p_full_name), 'active')
  RETURNING id INTO v_user_id;

  INSERT INTO public.platform_staff (user_id, role, status)
  VALUES (v_user_id, 'super_admin', 'active');

  RETURN QUERY SELECT v_user_id, lower(trim(p_email)), trim(p_full_name), 'super_admin'::TEXT;
END;
$function$

functions.claim_pairing_code:
CREATE OR REPLACE FUNCTION public.claim_pairing_code(p_code_hash text)
 RETURNS TABLE(pairing_code_id uuid, account_id uuid, board_instance_id uuid, account_status text, purpose text, requires_physical_confirmation boolean)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_row public.pairing_codes%ROWTYPE;
  v_account_status TEXT;
BEGIN
  SELECT * INTO v_row
  FROM public.pairing_codes
  WHERE code_hash = p_code_hash
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_row.used_at IS NOT NULL OR v_row.expires_at <= now() OR v_row.attempt_count >= v_row.max_attempts THEN
    UPDATE public.pairing_codes
    SET attempt_count = attempt_count + 1
    WHERE id = v_row.id;
    RETURN;
  END IF;

  SELECT a.status INTO v_account_status
  FROM public.accounts a
  WHERE a.id = v_row.account_id AND a.deleted_at IS NULL;

  IF v_account_status IS NULL OR v_account_status <> 'active' THEN
    RETURN;
  END IF;

  UPDATE public.pairing_codes
  SET used_at = now(),
      attempt_count = attempt_count + 1
  WHERE id = v_row.id;

  RETURN QUERY SELECT
    v_row.id,
    v_row.account_id,
    v_row.board_instance_id,
    v_account_status,
    v_row.purpose,
    v_row.requires_physical_confirmation;
END;
$function$

functions.resolve_admin_session_context:
CREATE OR REPLACE FUNCTION public.resolve_admin_session_context(p_token_hash text)
 RETURNS TABLE(session_id uuid, user_id uuid, email text, full_name text, appearance_preference text, timezone text, platform_staff_id uuid, platform_role text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_session_id UUID;
  v_user_id UUID;
  v_last_seen_at TIMESTAMPTZ;
  v_email TEXT;
  v_full_name TEXT;
  v_appearance TEXT;
  v_timezone TEXT;
  v_pstaff_id UUID;
  v_pstaff_role TEXT;
BEGIN
  SELECT s.id, s.user_id, s.last_seen_at
  INTO v_session_id, v_user_id, v_last_seen_at
  FROM public.sessions s
  WHERE s.token_hash = p_token_hash
    AND s.session_scope = 'admin_console'
    AND s.revoked_at IS NULL
    AND s.expires_at > now()
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT u.email, u.full_name, u.appearance_preference, u.timezone, ps.id, ps.role
  INTO v_email, v_full_name, v_appearance, v_timezone, v_pstaff_id, v_pstaff_role
  FROM public.users u
  JOIN public.platform_staff ps ON ps.user_id = u.id
  WHERE u.id = v_user_id
    AND u.user_kind = 'platform_admin'
    AND u.status = 'active'
    AND u.deleted_at IS NULL
    AND ps.status = 'active'
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_last_seen_at IS NULL OR v_last_seen_at < now() - INTERVAL '5 minutes' THEN
    UPDATE public.sessions
    SET last_seen_at = now()
    WHERE id = v_session_id;
  END IF;

  RETURN QUERY SELECT
    v_session_id,
    v_user_id,
    v_email,
    v_full_name,
    v_appearance,
    v_timezone,
    v_pstaff_id,
    v_pstaff_role;
END;
$function$

functions.resolve_pairing_board:
CREATE OR REPLACE FUNCTION public.resolve_pairing_board(p_code_id uuid, p_hardware_uid text, p_identity_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_code public.pairing_codes%ROWTYPE;
  v_target public.board_instances%ROWTYPE;
  v_existing uuid;
  v_matches integer;
BEGIN
  SELECT * INTO v_code FROM pairing_codes WHERE id = p_code_id;
  IF NOT FOUND OR v_code.used_at IS NULL THEN RAISE EXCEPTION 'Pairing code must be claimed first'; END IF;
  PERFORM id FROM accounts WHERE id = v_code.account_id FOR UPDATE;
  SELECT * INTO v_target FROM board_instances WHERE id = v_code.board_instance_id AND account_id = v_code.account_id FOR UPDATE;
  IF NOT FOUND OR v_target.deleted_at IS NOT NULL THEN RAISE EXCEPTION 'Target controller unavailable'; END IF;

  IF EXISTS (SELECT 1 FROM board_instances WHERE account_id <> v_code.account_id
    AND deleted_at IS NULL AND permanently_deleted_at IS NULL
    AND ((nullif(p_hardware_uid, '') IS NOT NULL AND
          upper(regexp_replace(hardware_uid, '[^a-fA-F0-9]', '', 'g')) = upper(regexp_replace(p_hardware_uid, '[^a-fA-F0-9]', '', 'g')))
      OR (nullif(p_identity_hash, '') IS NOT NULL AND board_instance_identity_secret_hash = p_identity_hash)))
  THEN RAISE EXCEPTION 'Board identity is already assigned to another account'; END IF;

  SELECT count(*), min(id::text)::uuid INTO v_matches, v_existing FROM board_instances
  WHERE account_id = v_code.account_id AND deleted_at IS NULL AND permanently_deleted_at IS NULL
    AND id <> v_target.id
    AND ((nullif(p_hardware_uid, '') IS NOT NULL AND
          upper(regexp_replace(hardware_uid, '[^a-fA-F0-9]', '', 'g')) = upper(regexp_replace(p_hardware_uid, '[^a-fA-F0-9]', '', 'g')))
      OR (nullif(p_identity_hash, '') IS NOT NULL AND board_instance_identity_secret_hash = p_identity_hash));
  IF v_matches > 1 THEN RAISE EXCEPTION 'Ambiguous installed board identity'; END IF;
  IF v_existing IS NOT NULL THEN
    -- Only an empty, never-paired provisional slot can be discarded.
    IF v_target.paired_at IS NOT NULL OR v_target.hardware_uid IS NOT NULL OR v_target.room_id IS NOT NULL OR v_target.assigned_controller_id IS NOT NULL
      OR EXISTS (SELECT 1 FROM devices WHERE board_instance_id = v_target.id)
      OR EXISTS (SELECT 1 FROM sensors WHERE board_instance_id = v_target.id)
      OR EXISTS (SELECT 1 FROM switches WHERE board_instance_id = v_target.id)
      OR EXISTS (SELECT 1 FROM board_instances WHERE assigned_controller_id = v_target.id)
    THEN RAISE EXCEPTION 'Cannot merge a controller with existing identity or assignments'; END IF;
    UPDATE pairing_codes SET board_instance_id = v_existing WHERE board_instance_id = v_target.id AND account_id = v_code.account_id;
    DELETE FROM board_instances WHERE id = v_target.id AND account_id = v_code.account_id;
    RETURN v_existing;
  END IF;
  -- Reserve the UID under the account lock before the rest of provisioning.
  IF nullif(p_hardware_uid, '') IS NOT NULL THEN
    UPDATE board_instances SET hardware_uid = p_hardware_uid WHERE id = v_target.id;
  END IF;
  RETURN v_target.id;
END;
$function$

functions.resolve_user_session_context:
CREATE OR REPLACE FUNCTION public.resolve_user_session_context(p_token_hash text)
 RETURNS TABLE(session_id uuid, user_id uuid, email text, full_name text, appearance_preference text, timezone text, account_id uuid, account_name text, account_slug text, account_status text, staff_id uuid, staff_role text)
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_session_id UUID;
  v_user_id UUID;
  v_active_account_id UUID;
  v_last_seen_at TIMESTAMPTZ;
  v_email TEXT;
  v_full_name TEXT;
  v_appearance TEXT;
  v_timezone TEXT;
  v_account_id UUID;
  v_account_name TEXT;
  v_account_slug TEXT;
  v_account_status TEXT;
  v_staff_id UUID;
  v_staff_role TEXT;
BEGIN
  SELECT s.id, s.user_id, s.active_account_id, s.last_seen_at
  INTO v_session_id, v_user_id, v_active_account_id, v_last_seen_at
  FROM public.sessions s
  WHERE s.token_hash = p_token_hash
    AND s.session_scope = 'user_console'
    AND s.revoked_at IS NULL
    AND s.expires_at > now()
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT u.email, u.full_name, u.appearance_preference, u.timezone
  INTO v_email, v_full_name, v_appearance, v_timezone
  FROM public.users u
  WHERE u.id = v_user_id
    AND u.user_kind = 'customer'
    AND u.status = 'active'
    AND u.deleted_at IS NULL
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  SELECT st.id, st.role, a.id, a.name, a.slug, a.status
  INTO v_staff_id, v_staff_role, v_account_id, v_account_name, v_account_slug, v_account_status
  FROM public.staff st
  JOIN public.accounts a ON a.id = st.account_id
  WHERE st.user_id = v_user_id
    AND st.status = 'active'
    AND a.deleted_at IS NULL
  ORDER BY (v_active_account_id IS NOT NULL AND st.account_id = v_active_account_id) DESC,
           st.created_at ASC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Throttle last_seen_at writes to once per 5 minutes to avoid write amplification on hot reads
  IF v_last_seen_at IS NULL OR v_last_seen_at < now() - INTERVAL '5 minutes' THEN
    UPDATE public.sessions
    SET last_seen_at = now()
    WHERE id = v_session_id;
  END IF;

  RETURN QUERY SELECT
    v_session_id,
    v_user_id,
    v_email,
    v_full_name,
    v_appearance,
    v_timezone,
    v_account_id,
    v_account_name,
    v_account_slug,
    v_account_status,
    v_staff_id,
    v_staff_role;
END;
$function$

functions.set_updated_at:
CREATE OR REPLACE FUNCTION public.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$function$
